{
  "overall_decision": "manual_review",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "credible_gap",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0010",
          "reason": "Succession and term-limit evidence belongs primarily in 4B/7B; it is not direct nuclear or existential-risk conduct."
        },
        {
          "evidence_id": "E0012",
          "reason": "This is the same term-limit/transition theme and should be treated as cross-chapter context, not 1B evidence."
        },
        {
          "evidence_id": "E0013",
          "reason": "Anti-money-laundering and proliferation-financing language is dual-use compliance context, not a ruler-specific nuclear-safety choice."
        },
        {
          "evidence_id": "E0015",
          "reason": "Broad climate and planetary-risk rhetoric is too diffuse to count as nuclear or existential-risk governance conduct."
        }
      ],
      "material_gaps": [
        {
          "gap": "There is no clear 2022 ruler-specific nuclear or existential-risk decision; the package is mostly treaty posture, institutional context, and broad rhetoric.",
          "lenses": ["1B.1", "1B.3", "1B.8", "1B.10"],
          "best_source_or_query_direction": "2022 NNRA/NAEC implementation records, presidential security directives, or IAEA/CTBTO operational documentation.",
          "why_it_matters": "Without a target-period choice, the chapter can only support limited-exposure contextualization rather than direct conduct."
        }
      ],
      "reason": "The package fairly establishes limited exposure, treaty baseline, and some restraint-oriented rhetoric, but most of the file is inherited posture or cross-chapter context rather than direct 2022 existential-risk conduct. It can support a cautious limited-exposure reading, not a strong conduct-based chapter presentation."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0025",
          "reason": "Use only as Buhari's claim; the VOA fact-check says the arms-flow assertion was unsubstantiated, so it cannot stand as established fact."
        },
        {
          "evidence_id": "E0029",
          "reason": "This ECOWAS summit is regional context and does not by itself show Buhari's individual conduct."
        }
      ],
      "material_gaps": [
        {
          "gap": "The package shows diplomacy, evacuation, and regional stabilization rhetoric, but no direct war-ending or ceasefire outcome clearly attributable to Buhari in 2022.",
          "lenses": ["2B.1", "2B.7", "2B.10"],
          "best_source_or_query_direction": "ECOWAS communiqués, UN/IGO records, or dated bilateral negotiation records tied to Buhari's own role.",
          "why_it_matters": "The chapter can be fairly presented, but the strongest evidence is still on posture and response rather than a concrete peace settlement."
        }
      ],
      "reason": "The file fairly separates Buhari's diplomacy and evacuation actions from contrary evidence and from one overclaimed security narrative. It is balanced enough for chapter use, provided the Lake Chad arms claim is treated as contested rhetoric rather than fact."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package adequately presents recurring state-linked abuse, protest repression, harsh detention conditions, and partial remedy, while preserving counterevidence and attribution caveats. It is strong enough for fair chapter presentation."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0055",
          "reason": "This is succession context, not evidence of democratic strengthening by itself."
        },
        {
          "evidence_id": "E0056",
          "reason": "This media-policy summary is indirect environment evidence, not a direct Buhari order."
        },
        {
          "evidence_id": "E0060",
          "reason": "This is continuing 2020 protest fallout, so it should be treated as trajectory context rather than a new 2022 decision."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct evidence on Buhari's personal tolerance of opposition, satire, and media scrutiny is thinner than the evidence on formal election-law moves and the Twitter-ban episode.",
          "lenses": ["4B.3", "4B.6", "4B.9"],
          "best_source_or_query_direction": "Primary court records, election-observer reports, and dated press-freedom documentation tied specifically to Buhari's 2022 decisions.",
          "why_it_matters": "The chapter can still be presented fairly, but the strongest material is legal/institutional rather than day-to-day political freedom behavior."
        }
      ],
      "reason": "The package is balanced and includes both reform evidence and adverse press/protest evidence. Some items are indirect or carry over from earlier years, but the file still fairly presents the 2022 political-freedom record."
    },
    {
      "chapter_id": "5B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Independent household-level welfare and sector-by-sector implementation evidence is thinner than macro-fiscal and policy-intent evidence.",
          "lenses": ["5B.6", "5B.8", "5B.10"],
          "best_source_or_query_direction": "Audited project reports, household survey outputs, and sector implementation reviews for health, education, jobs, and social protection.",
          "why_it_matters": "The chapter is fair as a mixed macro-and-policy record, but delivery quality and distributional effects are still not as independently grounded as the macro critique."
        }
      ],
      "reason": "The file fairly covers intent, fiscal management, subsidies, inflation, labor conditions, and adverse macro outcomes, with enough contrary evidence to avoid one-sidedness. It is usable as a chapter package."
    },
    {
      "chapter_id": "6B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0084",
          "reason": "This is an official self-report on program delivery counts and should be treated as weaker than audited outcome evidence."
        },
        {
          "evidence_id": "E0085",
          "reason": "This is also a self-reported delivery figure; it supports implementation claims but not independent outcome quality."
        },
        {
          "evidence_id": "E0090",
          "reason": "These survey gains span 2016-2021, so they are only partially attributable to Buhari in 2022."
        },
        {
          "evidence_id": "E0091",
          "reason": "This is a national poverty baseline and should be treated as context, not direct evidence of 2022 ruler conduct."
        },
        {
          "evidence_id": "E0092",
          "reason": "This is descriptive child-deprivation context and does not separate federal from state causation cleanly."
        }
      ],
      "material_gaps": [
        {
          "gap": "Independent evaluation of delivery quality for the major health and social-protection programs is thinner than the self-reported rollout counts and national survey context.",
          "lenses": ["6B.2", "6B.4", "6B.6", "6B.9"],
          "best_source_or_query_direction": "Program evaluations, audited health-system reports, and subnational implementation reviews for BHCPF, school feeding, and immunization rollout.",
          "why_it_matters": "The package is fair, but it leans on a mix of self-report and broad survey baseline evidence rather than fully independent delivery audits."
        }
      ],
      "reason": "The chapter file fairly combines positive program intent, some delivery evidence, and strong contrary welfare data. The main weakness is attribution and audit depth, not balance."
    },
    {
      "chapter_id": "7B",
      "decision": "manual_review",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0099",
          "reason": "This is Buhari's self-evaluation and should be treated as context, not independent evidence of honesty or integrity."
        },
        {
          "evidence_id": "E0038",
          "reason": "This press-freedom incident shows repression context, but the personal dishonesty nexus is indirect."
        },
        {
          "evidence_id": "E0039",
          "reason": "Same issue: it is a media-repression example, but not clean direct evidence of personal integrity or self-dealing."
        },
        {
          "evidence_id": "E0107",
          "reason": "This is policy-environment context around media freedom, not direct ruler-specific integrity evidence."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct evidence on assets, beneficial interests, procurement, campaign finance, hidden conflicts, or verified false statements remains thin.",
          "lenses": ["7B.3", "7B.4", "7B.6", "7B.7"],
          "best_source_or_query_direction": "Asset declarations, procurement/audit records, court or inquiry findings, and verified fact-checks of Buhari's own statements.",
          "why_it_matters": "The file has real evidence on patronage, censorship, and cabinet resignation rules, but the strongest personal-nexus integrity lenses are still under-supported."
        }
      ],
      "reason": "The package contains meaningful direct items on Twitter censorship, cabinet resignations, and a family-linked appointment, but it still leans heavily on context, repression, and self-report. The direct personal-nexus evidence is not yet strong enough for a clean review without human judgment."
    },
    {
      "chapter_id": "8B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0121",
          "reason": "This is a ministry self-report on project completion and should be treated as weaker than independent audit evidence."
        },
        {
          "evidence_id": "E0122",
          "reason": "This is a secondary summary page for a budget report and should be treated as proxy evidence, not the primary report itself."
        }
      ],
      "material_gaps": [
        {
          "gap": "Independent, audited completion data for the full 2022 priority portfolio is still thinner than the implementation-architecture and macro-diagnostics evidence.",
          "lenses": ["8B.6", "8B.7", "8B.8", "8B.10"],
          "best_source_or_query_direction": "Official budget-office completion reports, third-party project audits, and sector outcome evaluations tied to the 2022 program portfolio.",
          "why_it_matters": "The package fairly shows execution machinery and mixed outcomes, but the durability of program progress is still not fully audited across the whole agenda."
        }
      ],
      "reason": "The file fairly presents Buhari's 2022 program, staffing, coordination machinery, and mixed year-end results. It is strongest on program articulation and implementation architecture, and weaker only where it relies on self-reports rather than independent audits."
    }
  ]
}
